import { jsPDF } from "jspdf";


export const generatePdf = (teeth) => {

    console.log("Teeth ", teeth);
    const doc = new jsPDF();



    doc.setFontSize(16);
    doc.text("DentalIQ PDF Report", 20, 20);
    doc.setFontSize(12);
    doc.text("Acesta este un raport generat pentru pacient.", 20, 40);

    const pdfBlob = doc.output("blob");
    const blobUrl = URL.createObjectURL(pdfBlob);
    window.open(blobUrl); // Deschide în nou tab
};
